const input = $input.first().json;
const payload = input.body ?? input;
const message = payload.message ?? {};

const EXPECTED_FUNCTION_NAME = "reservar_cita";
const TIMEZONE = "Europe/Madrid";
const MEETING_DURATION_MINUTES = 30;
const MAX_ADVANCE_DAYS = 30;
const MINIMUM_NOTICE_HOURS = 2;

// --------------------------------------------------
// 1. Localizar la llamada de herramienta
// --------------------------------------------------

let toolCalls = [];

if (Array.isArray(message.toolCallList)) {
  toolCalls = message.toolCallList;
} else if (Array.isArray(message.toolCalls)) {
  toolCalls = message.toolCalls;
} else if (Array.isArray(message.toolWithToolCallList)) {
  toolCalls = message.toolWithToolCallList.map(
    (entry) => entry.toolCall ?? entry
  );
}

const toolCall = toolCalls[0] ?? null;

// --------------------------------------------------
// 2. Extraer argumentos
// --------------------------------------------------

let args =
  toolCall?.arguments ??
  toolCall?.parameters ??
  toolCall?.function?.arguments ??
  {};

if (typeof args === "string") {
  try {
    args = JSON.parse(args);
  } catch {
    args = {};
  }
}

if (!args || typeof args !== "object" || Array.isArray(args)) {
  args = {};
}

const cleanText = (value) => {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value)
    .replace(/\s+/g, " ")
    .trim();
};

// --------------------------------------------------
// 3. Normalizar parámetros
// --------------------------------------------------

const toolCallId = cleanText(toolCall?.id);

const functionName = cleanText(
  toolCall?.name ??
  toolCall?.function?.name
);

const clientName = cleanText(args.clientName);

const clientEmail = cleanText(
  args.clientEmail
).toLowerCase();

const businessName = cleanText(args.businessName);
const service = cleanText(args.service);
const projectSummary = cleanText(args.projectSummary);
const date = cleanText(args.date);
const startTime = cleanText(args.startTime);

// Información operativa de Vapi
const chatId = cleanText(
  message.chat?.id ??
  input.headers?.["x-chat-id"]
);

const callId = cleanText(
  message.call?.id ??
  message.assistant?.variableValues?.call?.id
);

// --------------------------------------------------
// 4. Funciones de validación
// --------------------------------------------------

const isValidEmail = (email) => {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
};

const parseCalendarDate = (value) => {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(
    value
  );

  if (!match) {
    return null;
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  const parsedDate = new Date(
    Date.UTC(year, month - 1, day)
  );

  const isRealDate =
    parsedDate.getUTCFullYear() === year &&
    parsedDate.getUTCMonth() === month - 1 &&
    parsedDate.getUTCDate() === day;

  return isRealDate ? parsedDate : null;
};

const getCurrentDateInTimezone = (timezone) => {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date());

  const values = {};

  for (const part of parts) {
    if (part.type !== "literal") {
      values[part.type] = part.value;
    }
  }

  return `${values.year}-${values.month}-${values.day}`;
};

const minutesToTime = (totalMinutes) => {
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;

  return `${String(hours).padStart(2, "0")}:${String(
    minutes
  ).padStart(2, "0")}`;
};

const localDateTimeToUtc = (
  dateString,
  totalMinutes,
  timezone
) => {
  const [year, month, day] = dateString
    .split("-")
    .map(Number);

  const hour = Math.floor(totalMinutes / 60);
  const minute = totalMinutes % 60;

  const desiredUtcValue = Date.UTC(
    year,
    month - 1,
    day,
    hour,
    minute,
    0
  );

  let utcGuess = desiredUtcValue;

  const formatter = new Intl.DateTimeFormat("en-GB", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  });

  for (let attempt = 0; attempt < 3; attempt++) {
    const parts = formatter.formatToParts(
      new Date(utcGuess)
    );

    const values = {};

    for (const part of parts) {
      if (part.type !== "literal") {
        values[part.type] = Number(part.value);
      }
    }

    const formattedUtcValue = Date.UTC(
      values.year,
      values.month - 1,
      values.day,
      values.hour,
      values.minute,
      values.second
    );

    const difference =
      desiredUtcValue - formattedUtcValue;

    utcGuess += difference;

    if (difference === 0) {
      break;
    }
  }

  return new Date(utcGuess);
};

// --------------------------------------------------
// 5. Validar datos obligatorios
// --------------------------------------------------

const errors = [];

if (!toolCall) {
  errors.push(
    "No se ha encontrado ninguna llamada de herramienta"
  );
}

if (!toolCallId) {
  errors.push(
    "Falta el identificador de la llamada de herramienta"
  );
}

if (!functionName) {
  errors.push("Falta el nombre de la función");
} else if (functionName !== EXPECTED_FUNCTION_NAME) {
  errors.push(
    `La función recibida es "${functionName}", pero se esperaba "${EXPECTED_FUNCTION_NAME}"`
  );
}

if (!clientName) {
  errors.push("Falta el nombre del cliente");
}

if (!clientEmail) {
  errors.push("Falta el correo electrónico");
} else if (!isValidEmail(clientEmail)) {
  errors.push(
    "El correo electrónico no tiene un formato válido"
  );
}

if (!businessName) {
  errors.push("Falta el nombre del negocio");
}

if (!service) {
  errors.push("Falta el servicio solicitado");
}

if (!projectSummary) {
  errors.push("Falta el resumen del proyecto");
}

// --------------------------------------------------
// 6. Validar fecha
// --------------------------------------------------

const requestedDate = parseCalendarDate(date);
const currentDate = getCurrentDateInTimezone(TIMEZONE);
const todayDate = parseCalendarDate(currentDate);

let daysInAdvance = null;
let isWeekend = false;

if (!date) {
  errors.push("Falta la fecha de la reunión");
} else if (!requestedDate) {
  errors.push(
    "La fecha debe ser una fecha real con formato YYYY-MM-DD"
  );
}

if (requestedDate && todayDate) {
  daysInAdvance = Math.round(
    (requestedDate.getTime() - todayDate.getTime()) /
      (24 * 60 * 60 * 1000)
  );

  const dayOfWeek = requestedDate.getUTCDay();
  isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

  if (daysInAdvance < 0) {
    errors.push(
      "No se puede reservar una reunión en una fecha pasada"
    );
  }

  if (daysInAdvance > MAX_ADVANCE_DAYS) {
    errors.push(
      `No se puede reservar con más de ${MAX_ADVANCE_DAYS} días de antelación`
    );
  }

  if (isWeekend) {
    errors.push(
      "NovaWeb Studio no ofrece reuniones los sábados ni los domingos"
    );
  }
}

// --------------------------------------------------
// 7. Validar hora y horario comercial
// --------------------------------------------------

const timeMatch =
  /^([01]\d|2[0-3]):([0-5]\d)$/.exec(startTime);

let startMinutes = null;
let endMinutes = null;
let endTime = "";
let startTimeUtc = "";
let endTimeUtc = "";

if (!startTime) {
  errors.push("Falta la hora de inicio");
} else if (!timeMatch) {
  errors.push(
    "La hora debe utilizar el formato HH:MM de 24 horas"
  );
} else {
  startMinutes =
    Number(timeMatch[1]) * 60 +
    Number(timeMatch[2]);

  endMinutes =
    startMinutes + MEETING_DURATION_MINUTES;

  endTime = minutesToTime(endMinutes);

  const startsOnValidBoundary =
    startMinutes % MEETING_DURATION_MINUTES === 0;

  const fitsMorning =
    startMinutes >= 10 * 60 &&
    endMinutes <= 14 * 60;

  const fitsAfternoon =
    startMinutes >= 16 * 60 &&
    endMinutes <= 18 * 60;

  if (!startsOnValidBoundary) {
    errors.push(
      "La reunión debe comenzar en un intervalo de 30 minutos"
    );
  }

  if (!fitsMorning && !fitsAfternoon) {
    errors.push(
      "La hora seleccionada está fuera del horario disponible"
    );
  }
}

// --------------------------------------------------
// 8. Convertir la cita a UTC
// --------------------------------------------------

if (
  requestedDate &&
  startMinutes !== null &&
  !isWeekend
) {
  const startDateUtc = localDateTimeToUtc(
    date,
    startMinutes,
    TIMEZONE
  );

  const endDateUtc = localDateTimeToUtc(
    date,
    endMinutes,
    TIMEZONE
  );

  startTimeUtc = startDateUtc.toISOString();
  endTimeUtc = endDateUtc.toISOString();

  const minimumAllowedTime =
    Date.now() +
    MINIMUM_NOTICE_HOURS * 60 * 60 * 1000;

  if (startDateUtc.getTime() < minimumAllowedTime) {
    errors.push(
      `La reunión debe reservarse con al menos ${MINIMUM_NOTICE_HOURS} horas de antelación`
    );
  }
}

// --------------------------------------------------
// 9. Preparar datos para Google Calendar
// --------------------------------------------------

const dateLabel = requestedDate
  ? new Intl.DateTimeFormat("es-ES", {
      weekday: "long",
      day: "numeric",
      month: "long",
      year: "numeric",
      timeZone: "UTC",
    }).format(
      new Date(`${date}T12:00:00.000Z`)
    )
  : "";

const eventTitle =
  clientName && businessName
    ? `Discovery Call — ${businessName} — ${clientName}`
    : "Discovery Call — NovaWeb Studio";

const eventDescription = [
  `Cliente: ${clientName}`,
  `Correo: ${clientEmail}`,
  `Negocio: ${businessName}`,
  `Servicio: ${service}`,
  `Objetivo: ${projectSummary}`,
  `Duración: ${MEETING_DURATION_MINUTES} minutos`,
  callId ? `Vapi Call ID: ${callId}` : "",
  chatId ? `Vapi Chat ID: ${chatId}` : "",
]
  .filter(Boolean)
  .join("\n");

const bookingKey = [
  clientEmail,
  date,
  startTime,
]
  .filter(Boolean)
  .join("|")
  .toLowerCase();

// --------------------------------------------------
// 10. Resultado
// --------------------------------------------------

return [
  {
    json: {
      toolCallId,
      functionName,

      clientName,
      clientEmail,
      businessName,
      service,
      projectSummary,

      date,
      dateLabel,
      startTime,
      endTime,
      timezone: TIMEZONE,
      meetingDurationMinutes: MEETING_DURATION_MINUTES,

      startTimeUtc,
      endTimeUtc,

      currentDate,
      daysInAdvance,
      isWeekend,

      eventTitle,
      eventDescription,
      bookingKey,

      chatId,
      callId,

      valid: errors.length === 0,
      errors,
    },
  },
];

const calendarResult = $input.first().json;

const booking = $(
  "Normalizar y validar reserva"
).first().json;

const available =
  calendarResult.available === true ||
  calendarResult.available === "true";

return [
  {
    json: {
      ...booking,
      available,
    },
  },
];

const event = $input.first().json;

const booking = $(
  "Normalizar y validar reserva"
).first().json;

const meetEntry = Array.isArray(
  event.conferenceData?.entryPoints
)
  ? event.conferenceData.entryPoints.find(
      (entry) => entry.entryPointType === "video"
    )
  : null;

const meetLink =
  event.hangoutLink ??
  meetEntry?.uri ??
  "";

const calendarEventId = String(
  event.id ?? ""
).trim();

const calendarLink = String(
  event.htmlLink ?? ""
).trim();

const calendarStatus = String(
  event.status ?? ""
).trim();

const bookingCreated =
  calendarEventId &&
  calendarStatus === "confirmed";

if (!bookingCreated) {
  throw new Error(
    "Google Calendar no ha confirmado la creación del evento"
  );
}

return [
  {
    json: {
      ...booking,

      bookingStatus: "CONFIRMED",
      calendarEventId,
      calendarStatus,
      calendarLink,
      meetLink,

      calendarStart:
        event.start?.dateTime ??
        booking.startTimeUtc,

      calendarEnd:
        event.end?.dateTime ??
        booking.endTimeUtc,

      calendarTimezone:
        event.start?.timeZone ??
        booking.timezone,

      attendeeResponseStatus:
        event.attendees?.[0]?.responseStatus ??
        "needsAction",

      calendarCreatedAt:
        event.created ??
        new Date().toISOString(),

      confirmedAt: new Date().toISOString(),
    },
  },
];

const booking = $input.first().json;

const toolCallId = String(
  booking.toolCallId ?? ""
).trim();

const calendarEventId = String(
  booking.calendarEventId ?? ""
).trim();

const bookingStatus = String(
  booking.bookingStatus ?? ""
).trim();

if (!toolCallId) {
  throw new Error(
    "No existe toolCallId para responder a Vapi"
  );
}

if (
  bookingStatus !== "CONFIRMED" ||
  !calendarEventId
) {
  const errorResult = {
    status: "booking_failed",
    message:
      "No se ha podido confirmar la creación de la reunión.",
    instruction:
      "No afirmes que la reunión está reservada. Indica que ha ocurrido un problema técnico y ofrece seguimiento por correo.",
  };

  return [
    {
      json: {
        results: [
          {
            toolCallId,
            error: JSON.stringify(errorResult),
          },
        ],
      },
    },
  ];
}

const successResult = {
  status: "booked",
  message: "La reunión se ha reservado correctamente.",

  clientName: booking.clientName,
  businessName: booking.businessName,

  date: booking.date,
  dateLabel: booking.dateLabel,
  startTime: booking.startTime,
  endTime: booking.endTime,
  timezone: booking.timezone,
  durationMinutes: booking.meetingDurationMinutes,

  calendarEventId,
  meetLink: booking.meetLink || null,
  calendarLink: booking.calendarLink || null,

  instruction:
    "Confirma al usuario que la reunión está reservada. Comunica la fecha, la hora y la duración. Indica que recibirá la invitación por correo y menciona que el enlace de Google Meet está incluido. Después pregunta si necesita algo más.",
};

return [
  {
    json: {
      results: [
        {
          toolCallId,
          result: JSON.stringify(successResult),
        },
      ],
    },
  },
];

const sourceItems = $(
  "Preparar reserva confirmada"
).all();

if (sourceItems.length === 0) {
  throw new Error(
    "No se han encontrado los datos de la reserva confirmada"
  );
}

const booking = sourceItems[0].json;

if (!booking.calendarEventId) {
  throw new Error(
    "La reserva no contiene un ID de evento de Google Calendar"
  );
}

if (booking.bookingStatus !== "CONFIRMED") {
  throw new Error(
    "La reserva recuperada no está confirmada"
  );
}

return [
  {
    json: {
      ...booking,

      vapiResponseSent: true,
      vapiResponseSentAt: new Date().toISOString(),

      crmStatus: "PENDING",
      confirmationEmailStatus: "PENDING",
    },
  },
];

const data = $input.first().json;

// --------------------------------------------------
// 1. Funciones auxiliares
// --------------------------------------------------

const escapeHtml = (value) => {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
};

const normalizarEnlace = (value, fieldName) => {
  let enlace = String(value ?? "").trim();

  // Admite también un enlace recibido accidentalmente
  // con formato Markdown: [texto](https://...)
  const markdownMatch = enlace.match(
    /^\[[^\]]+\]\((https:\/\/[^)]+)\)$/i
  );

  if (markdownMatch) {
    enlace = markdownMatch[1];
  }

  if (!/^https:\/\/[^\s"'<>]+$/i.test(enlace)) {
    throw new Error(
      `El campo ${fieldName} no contiene una URL HTTPS válida: ${enlace}`
    );
  }

  return enlace;
};

// --------------------------------------------------
// 2. Recuperación y validación de datos
// --------------------------------------------------

const appointmentDate = String(
  data.appointment_date ?? ""
).trim();

if (!/^\d{4}-\d{2}-\d{2}$/.test(appointmentDate)) {
  throw new Error(
    "La fecha de la reunión no utiliza el formato YYYY-MM-DD"
  );
}

const emailTo = String(
  data.client_email ?? ""
)
  .trim()
  .toLowerCase();

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailTo)) {
  throw new Error(
    `El correo del cliente no es válido: ${emailTo}`
  );
}

const meetLink = normalizarEnlace(
  data.meet_link,
  "meet_link"
);

const calendarLink = normalizarEnlace(
  data.calendar_link,
  "calendar_link"
);

// --------------------------------------------------
// 3. Preparación de los textos
// --------------------------------------------------

const dateForFormatting = new Date(
  `${appointmentDate}T12:00:00.000Z`
);

let dateLabel = new Intl.DateTimeFormat(
  "es-ES",
  {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }
).format(dateForFormatting);

dateLabel =
  dateLabel.charAt(0).toUpperCase() +
  dateLabel.slice(1);

const clientName = escapeHtml(data.client_name);
const businessName = escapeHtml(data.business_name);
const service = escapeHtml(data.service);
const startTime = escapeHtml(data.start_time);
const endTime = escapeHtml(data.end_time);
const timezone = escapeHtml(
  data.timezone || "Europe/Madrid"
);

const safeDateLabel = escapeHtml(dateLabel);
const safeMeetLink = escapeHtml(meetLink);
const safeCalendarLink = escapeHtml(calendarLink);

const emailSubject =
  `Reunión confirmada con NovaWeb Studio — ${dateLabel} a las ${data.start_time}`;

// --------------------------------------------------
// 4. HTML del correo
// --------------------------------------------------

const emailHtml = `
<!doctype html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width">
  <title>Reunión confirmada</title>
</head>

<body style="margin:0;padding:0;background-color:#f3f5f8;font-family:Arial,Helvetica,sans-serif;color:#172033;">

  <div style="display:none;max-height:0;overflow:hidden;opacity:0;">
    Tu reunión con NovaWeb Studio está confirmada para el ${safeDateLabel} a las ${startTime}.
  </div>

  <table
    role="presentation"
    width="100%"
    cellspacing="0"
    cellpadding="0"
    border="0"
    style="background-color:#f3f5f8;"
  >
    <tr>
      <td align="center" style="padding:32px 16px;">

        <table
          role="presentation"
          width="100%"
          cellspacing="0"
          cellpadding="0"
          border="0"
          style="max-width:620px;background:#ffffff;border:1px solid #dfe4ec;border-radius:16px;overflow:hidden;"
        >

          <!-- Cabecera -->
          <tr>
            <td style="padding:28px 32px;background:#172033;">
              <table
                role="presentation"
                width="100%"
                cellspacing="0"
                cellpadding="0"
                border="0"
              >
                <tr>
                  <td style="font-size:22px;font-weight:700;color:#ffffff;">
                    NovaWeb
                    <span style="color:#43d7a0;">
                      Studio
                    </span>
                  </td>

                  <td align="right">
                    <span style="display:inline-block;padding:8px 13px;background:#185f4d;border-radius:20px;color:#72e8ba;font-size:12px;font-weight:700;">
                      CONFIRMADA
                    </span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <!-- Contenido -->
          <tr>
            <td style="padding:36px 32px;">

              <div style="font-size:13px;font-weight:700;letter-spacing:1px;color:#218c68;">
                REUNIÓN RESERVADA
              </div>

              <h1 style="margin:12px 0 16px;font-size:28px;line-height:1.25;color:#172033;">
                Tu reunión está confirmada
              </h1>

              <p style="margin:0 0 24px;font-size:16px;line-height:1.6;color:#5a6578;">
                Hola
                <strong style="color:#172033;">
                  ${clientName}
                </strong>,
                hemos reservado correctamente tu reunión con
                NovaWeb Studio. La invitación también se ha enviado
                a tu calendario.
              </p>

              <!-- Detalles -->
              <table
                role="presentation"
                width="100%"
                cellspacing="0"
                cellpadding="0"
                border="0"
                style="border:1px solid #dfe4ec;border-radius:12px;border-collapse:separate;overflow:hidden;"
              >
                <tr>
                  <td
                    colspan="2"
                    style="padding:16px 20px;background:#f7f8fa;font-size:16px;font-weight:700;color:#172033;"
                  >
                    Detalles de la reunión
                  </td>
                </tr>

                <tr>
                  <td style="width:36%;padding:14px 20px;border-top:1px solid #dfe4ec;color:#778195;">
                    Fecha
                  </td>

                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;font-weight:700;color:#172033;">
                    ${safeDateLabel}
                  </td>
                </tr>

                <tr>
                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;color:#778195;">
                    Horario
                  </td>

                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;font-weight:700;color:#172033;">
                    ${startTime}–${endTime}
                  </td>
                </tr>

                <tr>
                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;color:#778195;">
                    Zona horaria
                  </td>

                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;font-weight:700;color:#172033;">
                    ${timezone}
                  </td>
                </tr>

                <tr>
                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;color:#778195;">
                    Negocio
                  </td>

                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;font-weight:700;color:#172033;">
                    ${businessName}
                  </td>
                </tr>

                <tr>
                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;color:#778195;">
                    Servicio
                  </td>

                  <td style="padding:14px 20px;border-top:1px solid #dfe4ec;font-weight:700;color:#172033;">
                    ${service}
                  </td>
                </tr>
              </table>

              <!-- Botones -->
              <table
                role="presentation"
                width="100%"
                cellspacing="0"
                cellpadding="0"
                border="0"
                style="margin-top:28px;"
              >
                <tr>
                  <td align="center">

                    <a
                      href="${safeMeetLink}"
                      target="_blank"
                      rel="noopener noreferrer"
                      style="display:inline-block;padding:14px 27px;background:#218c68;color:#ffffff;text-decoration:none;border-radius:28px;font-size:16px;font-weight:700;"
                    >
                      Acceder a Google Meet
                    </a>

                  </td>
                </tr>

                <tr>
                  <td align="center" style="padding-top:17px;">

                    <a
                      href="${safeCalendarLink}"
                      target="_blank"
                      rel="noopener noreferrer"
                      style="font-size:14px;color:#218c68;text-decoration:underline;"
                    >
                      Ver evento en Google Calendar
                    </a>

                  </td>
                </tr>
              </table>

