      ];

const toolResult = {
  status: "invalid_request",
  date: data.date || null,
  startTime: data.startTime || null,
  timezone: data.timezone || "Europe/Madrid",
  reasons,
  instruction:
    "Explica brevemente al usuario qué información falta o no es válida y solicita únicamente los datos necesarios para corregir la reserva. No digas que se ha producido un error técnico y no confirmes ninguna cita.",
